import{_ as t,a,c as n,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 41 Training elephants","description":"学习 with + 宾语 + 补足语，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 41 Training elephants","description":"学习 with + 宾语 + 补足语，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 with + 宾语 + 补足语，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 40 Waves","link":"/life/english/new-concept/book-4/unit-05/lesson-040"},"next":{"text":"第四册：流利英语 · Lesson 42 Recording an earthquake","link":"/life/english/new-concept/book-4/unit-06/lesson-042"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 40 Waves","link":"/life/english/new-concept/book-4/unit-05/lesson-040"},"next":{"text":"第四册：流利英语 · Lesson 42 Recording an earthquake","link":"/life/english/new-concept/book-4/unit-06/lesson-042"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-06/lesson-041.md","filePath":"life/english/new-concept/book-4/unit-06/lesson-041.md"}'),o={name:"life/english/new-concept/book-4/unit-06/lesson-041.md"};function s(l,e,r,h,d,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="第四册-流利英语-·-lesson-41-training-elephants" tabindex="-1">第四册：流利英语 · Lesson 41 Training elephants <a class="header-anchor" href="#第四册-流利英语-·-lesson-41-training-elephants" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 41 Training elephants&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-06/overview">单元 6</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>把驯象叙述作为历史文化材料阅读，识别叙事中的观察、控制手段与伦理假设。学习描述训练者声称的效果，不把历史做法自动当成值得复制的现代建议。重点用 with 复合结构组织伴随状态，讨论动物行为时保持观察性语言，避免凭单次动作断言情感或意图。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>handler</td><td>/ˈhændlə/</td><td>n.</td><td>动物训练或照管人员</td><td>an experienced handler</td></tr><tr><td>cue</td><td>/kjuː/</td><td>n.</td><td>提示信号</td><td>respond to a cue</td></tr><tr><td>welfare</td><td>/ˈwelfeə/</td><td>n.</td><td>福利；福祉</td><td>animal welfare</td></tr><tr><td>observation</td><td>/ˌɒbzəˈveɪʃən/</td><td>n.</td><td>观察</td><td>a recorded observation</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>respond to — 对信号作出反应</li><li>take account of — 将某因素考虑在内</li></ul><h2 id="语法讲解-with-宾语-补足语" tabindex="-1">语法讲解：with + 宾语 + 补足语 <a class="header-anchor" href="#语法讲解-with-宾语-补足语" aria-label="Permalink to &quot;语法讲解：with + 宾语 + 补足语&quot;">​</a></h2><p>with 复合结构可用名词加形容词、介词短语、现在分词、过去分词或不定式补充背景。with the gate open 表状态；with the trainer watching 表主动进行；with the task completed 表被动或完成。选择分词要看宾语与动作的关系，而不是主句主语。它只是组织信息的方式，并不自动说明因果；需要明确原因时，完整 because 从句更准确。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>With the observer standing at a distance, the handler recorded the animal’s response.</p></blockquote><p>观察者站在远处时，照管人员记录了动物的反应。</p><p>observer 与 standing 是主动关系；with 短语交代背景，主句主语是 handler。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>with the observer stood… 不能把一般过去时直接放入该结构；此处应用 standing。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读 with the observer standing 时不要在 observer 后断句；主句重新重读 handler，听辨两个角色。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The account describes an animal responding to a repeated cue. With no independent observations available, the claimed result is difficult to assess. A modern discussion should also consider the animal’s welfare.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句历史动物训练文本的批判性阅读笔记：叙述内容、证据限制、伦理问题。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>把叙述、可验证性和伦理分开，不提供强制训练操作。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：With the notes ___, the team ended the session.（complete 的过去分词）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> completed</p><p><strong>解析：</strong> notes 是被完成的，使用过去分词。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>示例中站在远处的是谁？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the observer</p><p><strong>解析：</strong> with 结构有自己的逻辑主语。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>with the gate open 中 open 是动词还是形容词？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 形容词。</p><p><strong>解析：</strong> 它作宾语 gate 的状态补足语。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：with + 宾语 + 补足语。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-06/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-06/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-06/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-040">上一课</a> · <a href="/life/english/new-concept/book-4/unit-06/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-06/lesson-042">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(o,[["render",s]]);export{u as __pageData,b as default};
